-- Учёный
INSERT INTO profession_details (profession_id, reality, daily_tasks, stress_level, education_path, career_path, pros, cons, ideal_for, avoid_if)
SELECT id,
'Не "гений в лаборатории". Это 95% неудач: опыт не воспроизвёлся, статью отклонили, грант не дали. Зато когда ты первый увидел то, что никто не видел — это наркотик.',
'8:00 — кофе, чтение статей (что сделали конкуренты за ночь). 9:00 — планирование опытов (что проверим, сколько раз). 10:00 — лаборатория (пипетки, пробирки, приборы). 13:00 — обед (обсуждение с коллегами "а вдруг мы ошиблись?"). 14:00 — анализ данных (Excel/Python/R — до вечера). 18:00 — написание отчёта/статьи. 20:00 — домой (или ночь в лабе, если "пошло").',
'Средний',
'Бакалавриат (4 года) → Магистратура (2 года) → Аспирантура (3-4 года, кандидат) → Докторантура (еще 3-5 лет, доктор). Или: исследователь в индустрии (без учёной степени, но с опытом).',
'Лаборант → Младший научный сотрудник → Старший научный сотрудник → Ведущий научный сотрудник → Зав. лабораторией / Директор института. Или: R&D в корпорации, консалтинг, свой стартап.',
'["Первым узнаешь то, что никто не знает", "Нет начальника над душой — ты сам планируешь", "Можно уехать на конференцию в Токио/Бостон", "Работа = хобби (если горишь)"]',
'["95% опытов неудач — и это норма", "Зарплата на старте — смешная", "Гранты — вечная гонка, пишешь заявки, а не делаешь науку", "Конкуренция жестокая (кто первый опубликовал — тот и учёный)", "Работа не заканчивается никогда"]',
'Любопытный до боли, терпеливый, не боящийся неудач. Тот, кто кайфует от "а что если?", готов проверять годами, не требуя быстрого результата.',
'Если нужен быстрый результат, деньги, признание. Если не переносите неопределённость ("а вдруг 3 года зря?"). Если важна социальная жизнь (лаборатория — это монастырь).'
FROM professions WHERE title = 'Учёный / Исследователь';

-- Врач
INSERT INTO profession_details (profession_id, reality, daily_tasks, stress_level, education_path, career_path, pros, cons, ideal_for, avoid_if)
SELECT id,
'Не "спаситель человечества". Это 12-часовые смены, ночные дежурства, смерть пациентов, которых ты не спас. И родители, которые кричат "вы убили нашего ребёнка". Но когда вытащил из комы — ты Бог. Буквально.',
'7:00 — сдача дежурства (кто умер за ночь, кого стабилизировали). 8:00 — обход (20 пациентов, 5 минут на каждого — и "не забудь улыбнуться"). 10:00 — приём (очередь из 30, половина — "а вдруг рак?"). 13:00 — обед (перекус за 10 минут, пока никто не умер). 14:00 — операции/процедуры/консилиумы. 18:00 — бумаги (истории болезней, выписки, рецепты). 19:00 — уходишь. Или нет — экстренное поступление.',
'Очень высокий',
'Медицинский университет (6 лет) → Интернатура (1 год) → Ординатура (2-4 года, специализация) → Врач. Или: медколледж (4 года) → фельдшер/медсестра → врач (через университет).',
'Врач → Старший врач → Заведующий отделением → Главный врач. Или: частная практика, научная карьера (PhD), медицинский директор в компании.',
'["Спасаешь жизни — реально", "Уважение в обществе (врач — всегда врач)", "Стабильность — люди болеют всегда", "Можно уехать работать в любую страну", "Никогда не скучно — каждый пациент уникален"]',
'["12-часовые смены, ночные дежурства", "Смерть — часть работы", "Родители/родственники кричат, угрожают", "Бюрократия (бумаги больше лечения)", "Выгорание через 5-7 лет — норма", "Малопонятная зарплата на старте"]',
'Стрессоустойчивый, эмпатичный, но с дистанцией ("сопереживаю, но не разрушаюсь"). Тот, кто готов учиться 10+ лет, не ждёт быстрого результата, способен принимать решения под давлением.',
'Если не переносите кровь/смерть/крики. Если хотите работать 9-18 и праздники. Если важна обратная связь ("спасибо" — редкость, чаще "вы плохой врач").'
FROM professions WHERE title = 'Врач / Медицинский работник';

-- Программист
INSERT INTO profession_details (profession_id, reality, daily_tasks, stress_level, education_path, career_path, pros, cons, ideal_for, avoid_if)
SELECT id,
'Не "гений в свитере". Это 8 часов гугления "почему не работает", Stack Overflow, кофе, мат. И "сделай за вчера" от менеджера. Зато когда код заработал — ты чувствуешь себя богом. До следующего бага.',
'9:00 — стендап (15 минут "что делал, что буду делать, что мешает"). 9:30 — кодинг (IDE, кофе, гугление). 12:00 — обед (с коллегами, обсуждение нового фреймворка). 13:00 — кодинг (ревью кода, баги, фичи). 16:00 — митинг (менеджер: "а почему не готово?"). 17:00 — кодинг (деплой в пятницу — нельзя, но придётся). 19:00 — домой. Или нет — production упал.',
'Средний',
'Университет (4-5 лет, Computer Science) → стажёр (3-6 мес) → junior → middle → senior. Или: курсы (6-12 мес) → junior. Или: самоучка (портфолио на GitHub) → junior.',
'Junior → Middle → Senior → Lead → Architect / Engineering Manager. Или: фриланс, свой стартап, консалтинг, переход в продукт/менеджмент.',
'["Работа из дома — норма", "Зарплата выше среднего (даже на старте)", "Можно работать из любой точки мира", "Спрос огромный — всегда найдёте работу", "Каждый день новое — технологии меняются"]',
'["Сидячая работа — спина, глаза, вес", "Выгорание через 3-5 лет — норма", "Вечное обучение (фреймворк устарел за полгода)", "Менеджеры не понимают, что сделать кнопку — это 2 недели", "Одиночество — даже в офисе общаешься с монитором"]',
'Логичный, любящий головоломки, терпеливый ("почему не работает" — может занять день). Тот, кто кайфует от "а вдруг получится?", готов учиться всю жизнь, не требует социальной работы.',
'Если хотите общаться с людьми, "творить" без ограничений, работать 9-18 без дедлайнов. Если не переносите сидячую работу и постоянное обучение.'
FROM professions WHERE title = 'Программист / Разработчик';
